/* Scenario content (data only). The UI lives in scenarios.js.
   Question types: single, multi (select all; partial credit), match (classify items), written (self-assessed).
   Review note: terminology follows the five lectures; the ISO 9126 sub-characteristics and Boehm details come from
   the standard textbook version because those slides were pictures. Please check against your lecturer's slides. */
const qSingle=(prompt,options,a,explain)=>({type:"single",prompt,options,answer:[a],explain,marks:1});
const qMulti=(prompt,options,a,explain)=>({type:"multi",prompt,options,answer:a,explain,marks:2});
const qMatch=(prompt,categories,items,explain)=>({type:"match",prompt,categories,items:items.map(([t,a])=>({t,a})),explain,marks:items.length});
const qWritten=(prompt,model)=>({type:"written",prompt,model,marks:0});
const sol=(problem,concepts,apply,recs,just,mistakes)=>({problem,concepts,apply,recs,just,mistakes});

const FURPS_CATS=["Functionality","Usability","Reliability","Performance","Supportability","+ Design","+ Implementation","+ Interface","+ Physical"];

const SCENARIOS=[
/* ======================= CHAPTER 1 ======================= */
{id:"ch1-late-excellent",title:"Excellent product, delivered late",chapter:1,category:"model-identification",difficulty:"easy",minutes:6,
 tags:["quality","fitness-for-purpose"],related:["c1-1","c1-2"],
 description:"A software house delivers a hospital reporting tool. Every technical requirement in the specification is met and testers found almost no bugs. However, the product arrives two months after the agreed delivery date and costs 40% more than the agreed budget. The client's manager says: “The software is good, but this is not what we agreed.”",
 questions:[
  qSingle("Does this delivery meet the lecture definition of quality?",["Yes, because all technical requirements were met","No. Quality also means meeting requirements at the agreed cost and within the agreed timescale","Yes, because testers found almost no bugs","Only if the client agrees to pay the extra cost later"],1,"Quality = meeting the customer's requirements at the agreed cost within the agreed timescales. Requirements alone are not enough."),
  qMulti("Select ALL elements that are part of that definition of quality.",["The customer's requirements","The agreed cost","The agreed timescale","The programmers' preferred tools"],[0,1,2],"Requirements, agreed cost and agreed timescale. Tool preference is not part of the definition."),
  qWritten("Explain whether quality was achieved here and give two actions to avoid this in future.","Quality was not fully achieved. Requirements were met, but cost and time agreements were broken, and the customer is dissatisfied (customer satisfaction, fitness for purpose). Actions: track predicted versus actual staff, equipment and time (variation control); review progress at milestones and renegotiate scope or budget early.")],
 hints:["Which three things does the definition of quality combine?","Which of requirements, cost and time were broken?","Connect the facts (2 months late, 40% over budget) to the definition.","Think about what could be monitored during the project.","Why is the client still unhappy even though the product works?"],
 solution:sol(["All requirements met, but 2 months late and 40% over budget.","The client is not satisfied."],["Definition of quality: requirements + agreed cost + agreed timescale.","Fitness for purpose and customer satisfaction."],["Requirements ✔, cost ✘, time ✘, so quality is incomplete.","Customer satisfaction suffers even if the product works."],["Track predicted vs actual effort, staff and time.","Review at milestones and renegotiate scope early."],"The lecture defines quality as meeting requirements at the agreed cost within the agreed timescale, so a good product that is late and over budget is not fully high quality.",["Thinking quality means only ‘few bugs’.","Ignoring cost and time because the product works."])},

{id:"ch1-explicit-implicit",title:"The app that logs in but crashes",chapter:1,category:"model-application",difficulty:"medium",minutes:10,
 tags:["pressman","explicit-implicit","quality"],related:["c1-3"],
 description:"A startup builds a customer app. The specification says: “Users can log in with email and password” and “The login page must have a Remember Me option.” Both work. In real use, however, the app crashes several times a day and stores passwords in plain text. Nobody wrote these expectations in the specification.",
 questions:[
  qSingle("Which part of Pressman's definition is mainly violated by the crashes and plain-text passwords?",["Explicit functional requirements","Implicit characteristics expected of professionally developed software","Only the documented development standards","The customer's brand perception"],1,"Nobody wrote them down, yet every professional product is expected to be stable and secure. These are implicit characteristics."),
  qMulti("Select ALL explicit requirements in this case.",["Users can log in with email and password","The app should not crash in normal use","Passwords should be stored securely","The login page has a Remember Me option"],[0,3],"Explicit = written in the specification. Stability and secure storage are implicit."),
  qSingle("Software meets its explicit requirements but fails implicit ones. According to the lecture, its quality is:",["Perfect","Suspect","Equal to its design quality","Automatically perceived quality"],1,"The lecture says that in this case software quality is suspect."),
  qWritten("Using Pressman's definition, explain why this software has a quality problem and what the team should change.","Pressman: quality = conformance to explicit functional and performance requirements, documented development standards, and implicit characteristics expected of all professionally developed software. The login meets explicit requirements, but crashes (reliability) and plain-text passwords (security) fail implicit expectations, so quality is suspect. Change: write implicit expectations as requirements (stability, secure storage), follow development standards, and test for them.")],
 hints:["Separate what was written in the specification from what was only expected.","Pressman names three things. Which one covers unwritten expectations?","Connect crashes and plain-text passwords to that third part.","What could the team do so unwritten expectations are not forgotten?","Why is ‘it passes the spec’ not a safe conclusion?"],
 solution:sol(["Stated requirements are met.","Crashes and weak password storage are not in the spec but hurt users."],["Pressman's definition: explicit requirements, documented standards, implicit characteristics."],["Login and Remember Me = explicit ✔.","Stability and secure storage = implicit ✘, so quality is suspect."],["Turn implicit expectations into written requirements.","Follow development standards and test for stability and security."],"Software that meets only the written requirements can still fail professional expectations, so the implicit part of the definition matters.",["Treating the specification as the whole definition of quality.","Calling the crashes ‘not a requirement’."])},

{id:"ch1-design-conformance",title:"Good design, wrong build",chapter:1,category:"model-identification",difficulty:"easy",minutes:6,
 tags:["design-conformance"],related:["c1-5","c1-6"],
 description:"The approved design for an online ticket system says pages must be responsive and load within 2 seconds. The developers, in a hurry, build a fixed-width layout without optimisation, and pages take 6 seconds on phones. The design document itself was reviewed and judged good.",
 questions:[
  qSingle("The main problem in this case is:",["Poor quality of design","Poor quality of conformance","Only poor perceived quality","A shortage of QC budget"],1,"The design is good, but the delivered product does not match it. That is conformance."),
  qMatch("Classify each statement.",["Quality of design","Quality of conformance"],[["The design document specifies a 2-second load time",0],["Delivered pages take 6 seconds",1],["Designers studied customer needs before drawing screens",0],["Code was written to follow the approved design within tolerance",1]],"Design = what the producer intends. Conformance = how well the product matches that design."),
  qSingle("The lecture says design is about ___ of product cost but ___ influence on quality.",["5% / 70%","70% / 5%","50% / 50%","20% / 20%"],0,"Design is 5% of cost but has 70% influence on quality.")],
 hints:["Was the plan wrong, or was the product not built according to the plan?","Compare ‘designed’ against ‘delivered’.","Which of the two quality types focuses on implementation?","Where should the team focus to fix this?","What does the 5% / 70% fact tell you about design?"],
 solution:sol(["Design is good, but the product misses its targets."],["Quality of design vs quality of conformance."],["Design says 2 s, product takes 6 s: conformance failure."],["Build to the design and test against targets and tolerances."],"Conformance measures how closely the produced product matches the design or specification.",["Blaming the design when the build is wrong."])},

{id:"ch1-objective-perceived",title:"Same speed, different trust",chapter:1,category:"problem-diagnosis",difficulty:"medium",minutes:10,
 tags:["objective-perceived"],related:["c1-7","c1-8"],
 description:"Two note-taking apps, NoteA and NoteB, have the same measured speed, features and crash rate. Surveys show students trust NoteA much more because it is a well-known brand with strong advertising. NoteB's team fixes many bugs and improves its objective quality, but a year later user perception has barely changed.",
 questions:[
  qSingle("The difference in trust is mainly caused by:",["Objective quality","Perceived quality","Quality of conformance","Variation control"],1,"Perceived quality is a subjective judgment based on brand, price and advertising."),
  qSingle("In the Mitra & Golder study, about how much of a quality change is reflected in perception in the first year?",["About 20%","About 50%","100%","None"],0,"Only about 20% in year one. The full effect takes around six years."),
  qSingle("What did the study find about brand reputation?",["High-reputation brands are rewarded 3 years quicker for increases and punished 1 year slower for decreases","Reputation has no effect","Low-reputation brands are rewarded quicker","Reputation only affects price"],0,"This is the ‘double advantage’ of high-reputation brands."),
  qWritten("Advise NoteB's manager on how to improve perceived quality.","Objective quality is already equal, so the gap is perception. Perception lags: only ~20% appears in year one and full effect takes about six years, so improvements need patience and consistency. Build reputation (reviews, reliable releases, clear communication) and avoid quality drops, which are punished faster and more strongly.")],
 hints:["Is the measured quality different between the apps?","Which type of quality depends on brand and advertising?","What does the research say about how fast perception changes?","What can NoteB do besides fixing bugs?","Why is a quality drop more dangerous than a rise is helpful?"],
 solution:sol(["Measured quality is the same, trust is different."],["Objective vs perceived quality.","Mitra & Golder findings."],["Same measurements = same objective quality.","Brand and advertising drive perceived quality; change takes years."],["Be consistent and patient; build reputation.","Avoid quality decreases."],"Perception, not objective quality, drives preference and sales, and it lags behind real changes.",["Expecting perception to change instantly.","Assuming better measurements automatically win customers."])},

{id:"ch1-variation",title:"Three months became six",chapter:1,category:"problem-diagnosis",difficulty:"medium",minutes:8,
 tags:["variation","qc"],related:["c1-4"],
 description:"A team estimated a project at 3 months with 4 developers and 2 test machines. It took 6 months, 7 developers and 4 test machines. Management has no data explaining why.",
 questions:[
  qSingle("This gap is best described as:",["Variation between predicted and actual resources","Quality of design","An intangible cost","Perceived quality"],0,"Variation: the difference between predicted and actual staff, equipment and time."),
  qMulti("Select ALL resources the lecture says should be compared (predicted vs actual).",["Staff","Equipment","Time","Developers' favourite language"],[0,1,2],"Staff, equipment and time."),
  qSingle("According to the lecture, variation is:",["The heart of quality control","A cost category","A testing technique","A recovery method"],0,"Variation is the heart of quality control."),
  qWritten("What would you measure and monitor to reduce this variation?","Record predicted versus actual staff, equipment and time at each milestone, find where the largest differences occur, and use the data to improve future estimates and plans. The aim is to minimise the difference between predicted and actual resources.")],
 hints:["What two things are being compared?","Which lecture concept is called the heart of quality control?","Which three resources does the lecture name?","How could the team see variation early?","How would data improve the next estimate?"],
 solution:sol(["Predicted: 3 months, 4 devs, 2 machines. Actual: 6, 7, 4."],["Variation control."],["Large gaps in staff, time and equipment."],["Track plan vs actual at milestones and learn from the gaps."],"Reducing variation between predicted and actual resources makes projects predictable and controllable.",["Treating it as a one-off bad luck event."])},

{id:"ch1-qc-release",title:"Checks before every release",chapter:1,category:"model-identification",difficulty:"easy",minutes:5,
 tags:["qc"],related:["c1-10"],
 description:"Before every release, a team runs test cases, reviews the code and removes the defects found. A small separate group does these checks. The company wants to run them more efficiently.",
 questions:[
  qSingle("These activities are mainly:",["Quality Control","Quality assurance framework design","Variation control","Perceived quality"],0,"QC monitors work and removes defects before shipment."),
  qMulti("Select ALL implementation approaches for QC named in the lecture.",["Fully automated","Entirely manual","A combination of automated tools and human interaction","Only customer feedback after release"],[0,1,2],"Automated, manual or a combination."),
  qSingle("The objective of quality control is to:",["Minimise produced defects and increase product quality","Increase marketing","Reduce the number of developers","Remove the need for testing"],0,"Minimise defects and increase product quality.")],
 hints:["Do the activities check the product or define the process?","Which lecture term involves reviews and defect removal before shipment?","Name the three ways QC can be implemented.","Which approach suits repeated checks?","What is the goal of QC?"],
 solution:sol(["Defects are found and removed before release."],["Quality control."],["Reviews and testing before shipment = QC."],["Automate repeatable checks; keep human review where judgement is needed."],"QC is checking the product to remove defects before shipment.",["Calling this QA (QA is the process framework)."])},

/* ======================= CHAPTER 2 ======================= */
{id:"ch2-banking-mccall",title:"Mobile banking: wrong balances",chapter:2,category:"model-identification",difficulty:"medium",minutes:10,
 tags:["mccall"],related:["c2-2","c2-3","c2-4"],
 description:"A mobile banking app sometimes shows wrong account balances. At night it often stops responding, so customers cannot transfer money. The team wants to describe these problems using McCall's model.",
 questions:[
  qMulti("Select ALL McCall factors most directly affected.",["Correctness","Reliability","Portability","Reusability"],[0,1],"Wrong balances = correctness (does it do what I want?). Failing at night = reliability (accurately all the time?)."),
  qSingle("Both factors belong to which McCall group?",["Product Operation","Product Revision","Product Transition","None"],0,"Correctness, reliability, efficiency, integrity and usability are Product Operation."),
  qSingle("McCall's quality factors describe the ___ of the software.",["External view (users)","Internal view (developers)","Cost","Testing view"],0,"Factors = external view, to specify. Criteria = internal view, to build. Metrics = to control."),
  qWritten("Explain how factors, criteria and metrics could be used to improve this app.","Factors (to specify): correctness and reliability. Criteria (to build): for example accuracy and error tolerance, simplicity. Metrics (to control): for example percentage of balance errors, and uptime or failed transfers per night. Specify with factors, build with criteria, control with metrics.")],
 hints:["Match the symptoms to the factor questions: ‘does it do what I want?’ and ‘accurately all the time?’.","Which group of McCall factors covers how the software operates?","Which view do factors describe: users or developers?","Which developer-side attributes support those factors?","What numbers would show improvement?"],
 solution:sol(["Wrong balances.","Unresponsive at night."],["McCall: correctness and reliability (Product Operation).","Factors, criteria, metrics."],["Wrong balance → correctness.","Night failures → reliability."],["Improve accuracy and error tolerance.","Measure balance errors and uptime."],"McCall separates what users expect (factors) from how developers build it (criteria) and how it is measured (metrics).",["Choosing portability or reusability: nothing in the case needs them."])},

{id:"ch2-modify-often",title:"A portal whose rules keep changing",chapter:2,category:"model-application",difficulty:"easy",minutes:6,
 tags:["mccall"],related:["c2-3"],
 description:"A government portal's rules change every few months. The team must fix bugs quickly, add new rules easily and test every change without much effort.",
 questions:[
  qMulti("Select ALL McCall factors the team needs most.",["Maintainability","Flexibility","Testability","Portability"],[0,1,2],"Fix, change and test are the three Product Revision factors."),
  qSingle("These factors belong to:",["Product Revision","Product Transition","Product Operation","None"],0,"Product Revision = ability to undergo changes."),
  qMatch("Match each slide question to its factor.",["Maintainability","Flexibility","Testability"],[["Can I fix it?",0],["Can I change it?",1],["Can I test it?",2]],"Fix → maintainability, change → flexibility, test → testability.")],
 hints:["Is the product being fixed, changed or tested?","Which McCall group is about changing software?","Recall the M-F-T trick.","Which factor asks ‘Can I change it?’","What would a team without these factors suffer?"],
 solution:sol(["Frequent rule changes, bug fixes and testing."],["Product Revision: maintainability, flexibility, testability."],["Fix → maintainability. Change → flexibility. Test → testability."],["Modular, well-structured code and easy-to-run tests."],"The need to change software often points to the Product Revision group.",["Selecting portability: the system is not moving to a new environment."])},

{id:"ch2-interop-portability",title:"Courier link and a Linux move",chapter:2,category:"model-application",difficulty:"medium",minutes:8,
 tags:["mccall"],related:["c2-3","c2-4"],
 description:"A logistics company's tracking system must exchange data with a courier partner's service. Next year the system will also move from Windows servers to Linux servers. Developers also want to reuse the route-calculation module in another product.",
 questions:[
  qMatch("Match each need to a McCall factor.",["Interoperability","Portability","Reusability","Efficiency"],[["Exchange data with the courier's service",0],["Move from Windows to Linux",1],["Reuse the route module in another product",2]],"Interface with another application = interoperability. Another machine/environment = portability. Reuse parts = reusability."),
  qSingle("All three needs belong to which McCall group?",["Product Transition","Product Revision","Product Operation","Product Cost"],0,"Portability, reusability and interoperability are Product Transition."),
  qSingle("Which criterion (independent modules) supports reuse and easier maintenance?",["Modularity","Accuracy","Completeness","Error tolerance"],0,"Modularity: the provision of highly independent modules.")],
 hints:["Is the system talking to another system, moving, or being reused?","Which McCall group is about new environments?","Match each need with the slide question for each factor.","Which criterion gives independent modules?","What trade-off might portable code bring?"],
 solution:sol(["Data exchange, platform move, module reuse."],["Product Transition: interoperability, portability, reusability."],["Courier link → interoperability.","Windows→Linux → portability.","Route module → reusability."],["Use standard interfaces and modular, hardware-independent design."],"All three are about adapting to new environments, which is what Product Transition describes.",["Mixing portability and interoperability."])},

{id:"ch2-security-slow",title:"Maximum security and maximum speed?",chapter:2,category:"problem-diagnosis",difficulty:"hard",minutes:14,
 tags:["mccall","tradeoffs"],related:["c2-4","c2-5","c2-10"],
 description:"A payment app adds OTP, fingerprint, device checks and full data encryption. Security is now excellent, but screens take 8 seconds to load and the app uses more memory. The product manager demands maximum security and maximum speed at the same time.",
 questions:[
  qSingle("Which relationship does this show?",["Integrity vs efficiency (inverse)","Maintainability vs flexibility (direct)","Correctness vs reliability (direct)","Usability vs maintainability (identical)"],0,"Access control needs extra code and processing: longer run time and more storage."),
  qSingle("What is the best response to the manager?",["Maximise all factors equally","Prioritise factors for this product, accept the trade-off and optimise where possible","Remove all security checks","Ignore the complaints about speed"],1,"You cannot maximise everything; select and prioritise factors, and justify the compromise."),
  qMulti("Select ALL relationship examples that appear in the lecture.",["Usability vs efficiency: inverse (better interface needs more code)","Maintainability vs flexibility: direct","Portable code may be less efficient","Improving correctness decreases reliability"],[0,1,2],"Correctness helps reliability, it does not decrease it."),
  qWritten("Recommend how to balance security and speed for this payment app and how to measure the result.","Integrity and efficiency are inversely related, so prioritise: for payments, integrity and reliability rank very high, but speed still matters to usability. Keep the essential checks, optimise the rest (cache, lighter screens), and avoid redundant checks. Measure: average screen load time, number of unauthorised access attempts blocked, and user satisfaction. Accept a small efficiency cost for security and explain the decision.")],
 hints:["Which two McCall factors are in conflict?","Is the relationship inverse or direct?","Can both be maximised? What must a team do instead?","Which checks are essential for payments?","How would you measure both speed and security?"],
 solution:sol(["Security up, speed down, memory up."],["McCall trade-off: integrity vs efficiency (inverse).","Selecting and prioritising factors."],["Extra checks add processing and storage."],["Prioritise essential security, optimise elsewhere.","Measure load time and blocked attacks."],"Some factors conflict, so quality engineering means choosing priorities and justifying the trade-off.",["Believing every factor can be maximised together."])},

{id:"ch2-iso-shop",title:"A shopping app with confusing screens",chapter:2,category:"model-identification",difficulty:"medium",minutes:10,
 tags:["iso-9126"],related:["c2-6"],
 description:"A shopping app has every required feature and calculates prices correctly. However, new users find the screens confusing, pages are slow, and the app drains the phone battery.",
 questions:[
  qMulti("Select ALL ISO/IEC 9126 characteristics with problems.",["Functionality","Usability","Efficiency","Portability"],[1,2],"Features and calculations are fine. Confusing screens = usability; slow and battery use = efficiency."),
  qSingle("ISO/IEC 9126 has how many quality characteristics?",["6","5","7","11"],0,"6 characteristics (27 sub-characteristics)."),
  qMatch("Match each situation to an ISO 9126 characteristic.",["Functionality","Reliability","Usability","Efficiency","Maintainability","Portability"],[["Screens are hard to understand and learn",2],["Response time and resource use are high",3],["The app must run on a new operating system",5],["The cause of a failure is hard to find",4]],"Understandability/learnability → usability. Time behaviour/resource use → efficiency. New platform → portability. Analysing failures → maintainability."),
  qWritten("Create a short checklist to evaluate this app across all six ISO/IEC 9126 characteristics.","Functionality: required features present and accurate. Reliability: few failures, recovers from errors. Usability: easy to understand, learn and operate. Efficiency: fast response, low resource use. Maintainability: easy to analyse, change and test. Portability: runs on other platforms, easy to install. Each sub-characteristic is evaluated by metrics.")],
 hints:["List what works and what does not.","Which characteristic covers ease of understanding and learning?","Which covers speed and resource consumption?","Name all six characteristics (F-R-U-E-M-P).","What would you measure for each?"],
 solution:sol(["Features correct.","Hard to use, slow, battery drain."],["ISO 9126: usability and efficiency."],["Confusing screens → usability.","Slow, battery drain → efficiency."],["Simplify screens, optimise loading and resource use."],"ISO 9126 describes quality through six characteristics, each refined into sub-characteristics and evaluated with metrics.",["Blaming functionality although the features work."])},

{id:"ch2-boehm-legacy",title:"A legacy system nobody understands",chapter:2,category:"model-application",difficulty:"medium",minutes:10,
 tags:["boehm"],related:["c2-7"],
 description:"A company's 12-year-old inventory system works well for daily staff: it is easy to use, reliable and quick. But new developers cannot understand the code, and every change breaks something. The system may also need to move to a new environment.",
 questions:[
  qSingle("In Boehm's model this case shows good ___ but poor ___.",["as-is utility / maintainability","maintainability / as-is utility","portability / as-is utility","as-is utility / efficiency"],0,"As-is utility (easy to use, reliable, efficient) is fine; maintainability is poor."),
  qMulti("Select ALL sub-characteristics of maintainability in Boehm's model.",["Testability","Understandability","Flexibility / modifiability","Ease of use"],[0,1,2],"Ease of use belongs to as-is utility."),
  qSingle("Moving the system to a new environment relates to:",["Portability","Maintainability","As-is utility","Efficiency"],0,"Portability: ease of changing software to accommodate a new environment."),
  qWritten("Using Boehm's three primary uses, explain the strengths and weaknesses of this system and what to improve.","As-is utility is strong (ease of use, reliability, efficiency). Maintainability is weak: code is hard to understand and modify (understandability, modifiability, testability). Portability is a future concern. Improve understandability (documentation, structure), modifiability and testability, then prepare for portability.")],
 hints:["Boehm has three primary uses: which?","Which use is the current daily experience?","Which sub-characteristics describe the developers' problems?","Which use covers the possible move?","What improvement helps new developers?"],
 solution:sol(["Daily use is fine; changes are hard."],["Boehm: as-is utility, maintainability, portability."],["Fine for users → as-is utility.","Hard to change → maintainability.","New environment → portability."],["Improve understandability and modifiability; add tests."],"Boehm separates how the software is used now from how easily it can be changed or moved.",["Treating ‘works today’ as ‘high quality overall’."])},

{id:"ch2-furps-hospital",title:"Classifying hospital requirements",chapter:2,category:"model-application",difficulty:"medium",minutes:10,
 tags:["furps"],related:["c2-8"],
 description:"A hospital system must: let doctors register patients and view records; be easy for doctors to learn, with online help; run 24 hours a day, 7 days a week; open a patient record within 2 seconds; be extendable with new departments later; use a relational database; be written in Java; connect to the laboratory machine; and run on a tablet that weighs less than 500 g.",
 questions:[
  qMatch("Classify each requirement using FURPS+.",FURPS_CATS,[["Register patients and view records",0],["Easy to learn, with online help",1],["Run 24 hours a day, 7 days a week",2],["Open a patient record within 2 seconds",3],["Extendable with new departments later",4],["Use a relational database",5],["Written in Java",6],["Connect to the laboratory machine",7],["Tablet weighs less than 500 g",8]],"F = functions, U = usability/help, R = availability, P = response time, S = extend/adapt, +Design = relational DB, +Implementation = language, +Interface = external item, +Physical = size/weight."),
  qSingle("FURPS was proposed by:",["Robert Grady at Hewlett Packard","Barry Boehm","McCall, Richards and Walters","ISO"],0,"Grady at HP in 1987, later extended by IBM as FURPS+.")],
 hints:["Is the requirement about what the system does, or a constraint on it?","‘Run 24/7’ is about availability.","Technology choices are constraints.","Hardware limits are physical requirements.","Connecting to another item is an interface requirement."],
 solution:sol(["Nine different kinds of requirement in one case."],["FURPS and FURPS+."],["Functional: register, view. Constraints: database, language, device size."],["Classify early so each type gets proper design and tests."],"FURPS+ organises requirements, including constraints, so none is forgotten.",["Calling every non-functional item ‘performance’."])},

{id:"ch2-gqm-crashes",title:"Reducing crashes with GQM",chapter:2,category:"solution-design",difficulty:"medium",minutes:12,
 tags:["gqm"],related:["c2-9"],
 description:"A company wants to reduce crashes in its mobile app. Managers say: “We need fewer crashes.” The team is asked to define what to ask and what to measure so progress can be checked every release.",
 questions:[
  qMatch("Classify each statement as a Goal, a Question or a Metric.",["Goal","Question","Metric"],[["Reduce application crashes by 50%",0],["How often does the app crash during normal use?",1],["Crashes per 1000 user sessions",2],["Are testers finding crash bugs before release?",1],["Crash defects found in testing per release",2]],"Goal = what we want. Question = what must be answered to know if we meet it. Metric = what we measure."),
  qSingle("In GQM, Goal is the ___ level, Question the ___ level and Metric the ___ level.",["conceptual / operational / quantitative","operational / conceptual / quantitative","quantitative / operational / conceptual","technical / social / financial"],0,"Conceptual, operational, quantitative."),
  qSingle("A team proposes ‘number of developers’ as the metric for the question ‘How often does the app crash?’ What is wrong?",["The metric does not help answer the question","The question is really a goal","Metrics must be qualitative","Nothing is wrong"],0,"A metric must measure what the question asks."),
  qWritten("Write one GQM chain (Goal → Questions → Metrics) for this company.","Goal: reduce app crashes by 50% in two releases. Question 1: how often does the app crash in normal use? Metric: crashes per 1000 sessions. Question 2: are crash bugs found before release? Metric: crash defects found in testing per release.")],
 hints:["Which statement says what the company wants to achieve?","Questions help decide if the goal is being met.","Metrics are numbers or measurements.","Check each metric answers its question.","Write Goal first, then Questions, then Metrics."],
 solution:sol(["Managers want fewer crashes but nothing is defined."],["GQM: Goal, Question, Metric."],["Goal → questions → metrics, each answering the one before."],["Track crashes per 1000 sessions each release."],"GQM links measurement to a goal so numbers are collected for a reason.",["Choosing metrics first, with no goal or question."])},

{id:"ch2-model-selection",title:"Which model for which need?",chapter:2,category:"model-comparison",difficulty:"hard",minutes:14,
 tags:["model-selection","mccall","iso-9126","boehm","furps","gqm"],related:["c2-1","c2-10"],
 description:"A company is building a new patient portal. Different managers ask different things: (a) classify all requirements, including technology and hardware constraints; (b) evaluate the product against six quality characteristics; (c) define factors, criteria and metrics for developers; (d) discuss as-is utility, maintainability and portability; (e) measure whether the goal “reduce failed bookings” is achieved.",
 questions:[
  qMatch("Which model best fits each request?",["FURPS+","ISO/IEC 9126","McCall","Boehm","GQM"],[["(a) Classify requirements including constraints",0],["(b) Six quality characteristics",1],["(c) Factors, criteria and metrics for developers",2],["(d) As-is utility, maintainability, portability",3],["(e) Measure whether an improvement goal is achieved",4]],"Each model has its own structure; match the structure to the request."),
  qSingle("Can more than one model be useful for the same system?",["Yes. Models overlap and each gives a different view","No. Only one model may be used","Only GQM can be combined with others","Only for hardware systems"],0,"Models overlap. Choose by suitability and justify; there is not always one right model."),
  qWritten("The patient portal must be secure, always available, easy for older patients and measurable. Select two models and justify what each adds.","Example: FURPS+ to classify requirements (security under functionality or constraints, availability under reliability, usability for older patients, and technology constraints). GQM to measure success, for example goal ‘reduce failed bookings’ with questions and metrics. ISO 9126 or McCall could add a broader checklist. A good answer explains what each model contributes, not just names it.")],
 hints:["Each request describes the structure of one model.","Which model has ‘factors, criteria, metrics’?","Which model is about goals and measurement?","Which model has exactly six characteristics?","For the written answer: what does each model add?"],
 solution:sol(["Five different needs, five models."],["FURPS+, ISO 9126, McCall, Boehm, GQM."],["Match the request to the model's structure."],["Use more than one model where they add different value."],"Models overlap, so the best answer explains suitability rather than naming a single winner.",["Memorising only one ‘correct’ model per case."])},

{id:"ch2-hospital-integrated",title:"Hospital management system (integrated case)",chapter:2,category:"integrated",difficulty:"hard",minutes:20,
 tags:["mccall","iso-9126","furps","gqm","integrated"],related:["c2-3","c2-6","c2-8","c2-9"],
 description:"A hospital deploys a patient management system. Doctors report that patient records sometimes become unavailable during network failures. Patient information takes 15 seconds to load. Unauthorized employees can access confidential records. The hospital also wants to integrate a new laboratory service.",
 questions:[
  qMulti("Select ALL main quality concerns described.",["Reliability: records unavailable during network failure","Efficiency: 15-second record loading","Integrity: unauthorized access to records","Portability: moving to a new operating system","Interoperability: integrating the laboratory service"],[0,1,2,4],"Nothing in the case mentions a platform change, so portability is not relevant."),
  qMulti("Select ALL suitable McCall factors.",["Reliability","Efficiency","Integrity","Interoperability","Reusability"],[0,1,2,3],"Reliability, efficiency, integrity and interoperability."),
  qMatch("Classify each requirement using FURPS+.",FURPS_CATS,[["Records must stay available and recover after failures",2],["Records must open in under 3 seconds",3],["Doctors can view and update patient records",0],["The system must exchange data with the laboratory service",7]],"Availability/recovery → reliability. Response time → performance. What it does → functionality. External item → interface."),
  qSingle("Which ISO/IEC 9126 characteristic is NOT automatically relevant here?",["Portability","Reliability","Efficiency","Functionality"],0,"Portability only matters if a new environment or platform is specified."),
  qSingle("Which metric best measures the speed problem?",["Average seconds to open a patient record","Number of nurses","Colour of the interface","Hospital size"],0,"A metric must measure the quality concern."),
  qWritten("Recommend improvements with measurable metrics, and justify using more than one model.","Problems: availability under network failure, slow loading, weak access control, laboratory integration. McCall: reliability, efficiency, integrity, interoperability. ISO 9126: reliability, efficiency, functionality (including security considerations). FURPS+: reliability (availability, recovery), performance (response time), functionality, interface. Actions and metrics: improve recovery and backups (availability %, failed transactions); optimise queries (average load time); role-based access control (unauthorized access attempts); test the lab interface (successful exchanges). Each model adds a different view, so use them together.")],
 hints:["List the four problems in the case.","Match each problem to a McCall factor.","Which ISO 9126 characteristic would you NOT select, and why?","Which FURPS+ letters apply to availability, speed and the lab link?","Write a GQM-style measure for each recommendation."],
 solution:sol(["Records unavailable in failures.","15-second loading.","Unauthorized access.","Laboratory integration needed."],["McCall: reliability, efficiency, integrity, interoperability.","ISO 9126: reliability, efficiency, functionality.","FURPS+: R, P, F, interface."],["Network failure → reliability.","15 s → efficiency / performance.","Unauthorized access → integrity.","Lab service → interoperability / interface."],["Better recovery and backups; measure availability and failed transactions.","Optimise queries; measure load time.","Role-based access; measure unauthorized attempts.","Interface testing; measure successful exchanges."],"The case has several quality dimensions; each model contributes a different view, and the answer should explain what each adds.",["Naming models without applying them.","Selecting portability without a platform change."])},

/* ======================= CHAPTER 3 ======================= */
{id:"ch3-cost-classify",title:"Where does the quality money go?",chapter:3,category:"model-application",difficulty:"easy",minutes:8,
 tags:["cost","prevention","appraisal","failure","intangible"],related:["c3-1","c3-2","c3-3","c3-4","c3-5"],
 description:"A software company wants to understand where its quality money is going. Its finance team lists these activities and consequences.",
 questions:[
  qMatch("Classify each item.",["Prevention","Appraisal","Internal failure","External failure","Intangible"],[["Training developers to avoid recurring mistakes",0],["Inspecting code and running tests before release",1],["Fixing a bug found in testing and re-testing",2],["Customer refunds and help-line calls after release",3],["Lost sales because of a bad reputation",4],["A Six Sigma quality improvement programme",0],["Maintaining test equipment",1],["Warranty claims",3]],"Prevention stops defects; appraisal finds them before shipment; internal failure = found before shipment; external = after delivery; intangible = hidden image cost."),
  qSingle("Cost of GOOD quality is:",["Prevention + appraisal","Internal + external failure","Intangible costs only","Appraisal + external failure"],0,"Good = prevention + appraisal. Poor = failures + intangible costs.")],
 hints:["Does it stop defects, find them, or result from them?","Before or after shipment?","Which costs are hidden and hard to quantify?","Name the two costs of good quality.","Name the costs of poor quality."],
 solution:sol(["Mixed list of quality-related spending."],["Prevention, appraisal, internal failure, external failure, intangible."],["Classify by purpose and timing."],["Shift spend toward prevention."],"Classifying costs shows how much is spent on doing things right versus fixing failures.",["Putting rework after release under internal failure."])},

{id:"ch3-refund",title:"A billing defect reaches customers",chapter:3,category:"problem-diagnosis",difficulty:"medium",minutes:10,
 tags:["cost","failure","intangible"],related:["c3-4","c3-5"],
 description:"After deployment, customers find a billing defect. The company issues refunds, its help line is overloaded, a lawyer's letter arrives, and many customers leave and tell others the product is unreliable. The defect would have been caught by a review that was skipped to save money.",
 questions:[
  qMulti("Select ALL external failure costs.",["Refunds / product return","Help-line support","Legal liability","Staff training"],[0,1,2],"Staff training is prevention."),
  qSingle("Lost customer goodwill and reputation is a(n):",["Intangible cost","Appraisal cost","Prevention cost","Internal failure cost"],0,"Intangible: hidden, effects felt later."),
  qSingle("The lecture says intangible costs can be:",["3 or 4 times greater than tangible costs","Equal to tangible costs","Always zero","Half of tangible costs"],0,"3 or 4 times greater."),
  qSingle("The skipped review would have been what kind of cost?",["Appraisal (inspection)","Internal failure","External failure","Intangible"],0,"Inspections are appraisal costs."),
  qWritten("Explain how skipping the review changed the company's costs and what it should do next time.","Saving the appraisal cost caused far larger external failure costs (refunds, help line, legal liability) and intangible costs (lost goodwill, lost sales). Next time: invest in prevention and appraisal, because cost of good quality is much lower than cost of poor quality.")],
 hints:["Which costs happen after delivery?","Which costs are hard to quantify?","What type of cost was saved by skipping the review?","Compare the saving with the result.","What should the company spend on instead?"],
 solution:sol(["Defect in the field, refunds, help line, legal letter, lost customers."],["External failure and intangible costs."],["Refunds, help line, legal = external. Lost goodwill = intangible."],["Do reviews and testing; invest in prevention."],"Skipping an inexpensive appraisal activity caused much larger failure and intangible costs.",["Treating intangible costs as zero because they can't be quantified."])},

{id:"ch3-1-10-100",title:"A requirements mistake that cost Rs 200,000",chapter:3,category:"solution-design",difficulty:"medium",minutes:10,
 tags:["1-10-100","cost"],related:["c3-7","c3-9"],
 description:"A requirements mistake would cost about Rs 2,000 to prevent through a proper requirements review. The team skips the review. The mistake is found after the product is delivered.",
 questions:[
  qSingle("Using the 1-10-100 rule as an illustration, correcting it during development costs about:",["Rs 20,000","Rs 2,000","Rs 200,000","Rs 4,000"],0,"Prevention 1× = Rs 2,000, correction 10× = Rs 20,000."),
  qSingle("If it becomes a failure in the field it costs about:",["Rs 200,000","Rs 20,000","Rs 2,000","Rs 2,000,000"],0,"Failure 100× = Rs 200,000."),
  qSingle("Why does repair cost rise the later a defect is found?",["The defect spreads into design, code and tests and affects customers","Developers are paid more later","Hardware ages","Prevention costs more"],0,"Later phases add rework and external failure costs."),
  qWritten("Explain the rule and advise the team.","The 1-10-100 rule: $1 on prevention saves $10 on correction and $100 on failure. Here Rs 2,000 of prevention could have avoided about Rs 200,000 of failure. Advise: invest in early reviews and prevention. The numbers are an illustration of the principle, not exact data.")],
 hints:["What is the prevention cost?","Multiply for correction and for failure.","Where was the defect found?","Why is late repair expensive?","What would you change?"],
 solution:sol(["Skipped a Rs 2,000 review."],["1-10-100 rule; repair cost of defects."],["Prevention 1×, correction 10×, failure 100×."],["Do early reviews and prevention."],"The later a defect is found the more it costs.",["Treating the rule as exact data."])},

{id:"ch3-ecl",title:"100% conformance at any price",chapter:3,category:"solution-design",difficulty:"hard",minutes:14,
 tags:["ecl","cost"],related:["c3-8"],
 description:"A company decided to reach 100% conformance. It hired many inspectors and bought expensive test tools. Prevention and appraisal costs are now so high that total quality cost is higher than before, even though almost no failures reach customers.",
 questions:[
  qSingle("Total quality cost plotted against conformance level is:",["U-shaped","A straight rising line","A straight falling line","Flat"],0,"Control costs rise and failure costs fall, so the total is U-shaped."),
  qSingle("Prevention + appraisal costs ___ and failure costs ___ as conformance rises.",["increase / decrease","decrease / increase","both increase","both decrease"],0,"They move in opposite directions."),
  qSingle("The Economic Conformance Level (ECL) is:",["The level where total cost is lowest","Always 100% conformance","Always 0% conformance","The level where failures reach zero"],0,"The slide describes prevention + appraisal balancing failure costs, the lowest point of the total."),
  qSingle("Best advice for this company:",["Move toward the ECL: reduce excessive control while watching failure costs","Increase inspection further","Remove all testing","Ignore costs"],0,"Both too little and too much control cost money."),
  qWritten("Explain the company's mistake using the Quality Cost Conformance model.","The company pushed conformance beyond the economic level: prevention and appraisal costs grew faster than the failure costs they saved, so total cost moved up the U-curve. The best level (ECL) is where total cost is lowest. Reduce excessive checking, keep effective prevention, and monitor failure costs. Safety-critical products may justify a higher level.")],
 hints:["What shape is the total cost?","Which cost rises and which falls?","Where is the lowest total?","Is 100% always the best?","How would you find the better level?"],
 solution:sol(["Almost no failures but very high control costs."],["Quality Cost Conformance model, ECL."],["Too far right on the curve: control cost outweighs savings."],["Reduce excess checking, keep effective prevention."],"The economic best is the lowest total cost, not the highest possible conformance.",["Assuming more quality control is always better."])},

/* ======================= CHAPTER 4 ======================= */
{id:"ch4-training",title:"Same coding errors again and again",chapter:4,category:"solution-design",difficulty:"easy",minutes:8,
 tags:["qa","prevention-techniques"],related:["c4-3","c4-4","c4-5"],
 description:"A team keeps introducing the same coding errors. Investigation shows developers misunderstand the banking domain, do not know the testing tools, and do not follow the coding standard.",
 questions:[
  qSingle("The best-fit QA approach is:",["Defect prevention","Defect containment","Dynamic testing only","Fault injection"],0,"Remove the sources of the errors: defect prevention."),
  qMulti("Select ALL defect-prevention techniques.",["Education and training","Process conformance and standards enforcement","Tools/technologies and techniques","Black-box testing"],[0,1,2],"Black-box testing is defect reduction."),
  qMatch("Match each problem to the training focus area.",["Product/domain knowledge","Tool knowledge","General development knowledge","Development process knowledge"],[["Developers do not understand banking",0],["Developers cannot use the testing tool",1],["Weak requirements analysis skills",2],["Team does not know how increments fit together",3]],"Four focus areas: product/domain, tools, general development, process."),
  qSingle("Finding and fixing the root causes of human errors is called:",["Error source removal","Fault injection","Walkthrough","Voting"],0,"Error source removal.")],
 hints:["Is the problem about finding bugs or stopping them being injected?","Which QA category is first in the scheme?","Name the three prevention techniques.","What does each training area cover?","Which root causes are mentioned?"],
 solution:sol(["Repeated errors from lack of knowledge and standards."],["Defect prevention: training, standards, tools."],["Domain, tool and process gaps → education and training."],["Train, enforce standards, use supporting tools."],"Preventing faults from being injected is cheaper than finding them later.",["Choosing testing to solve a knowledge problem."])},

{id:"ch4-review-types",title:"Choosing the right review or test",chapter:4,category:"model-comparison",difficulty:"medium",minutes:12,
 tags:["inspection","walkthrough","desk-check","black-white","qa","qc"],related:["c4-1","c4-6","c4-7","c4-8"],
 description:"A QA team uses several activities: (1) several reviewers formally inspect requirements and code, with planning and follow-up; (2) a developer checks their own logic by walking test data through the code; (3) a small team reads the code together in a session; (4) a tester checks outputs against the requirements without seeing the source code; (5) a tester examines branches and internal structure. Before this, the company only checked the final product and had no quality process.",
 questions:[
  qMatch("Match each activity to its name.",["Inspection","Walkthrough","Desk checking","Black-box testing","White-box testing"],[["(1) Formal review by several reviewers",0],["(2) Developer checks own logic with test data",2],["(3) Team reads code together",1],["(4) Check outputs against requirements without code",3],["(5) Examine branches and internal structure",4]],"Inspection: multiple inspectors with planning and follow-up. Desk check: one person. Walkthrough: group code reading."),
  qMulti("Select ALL static testing activities.",["Inspection","Walkthrough","Desk checking","Black-box testing"],[0,1,2],"Static = no execution. Black-box testing runs the program."),
  qSingle("Checking only the final product with no quality process is mainly:",["QC without QA","QA without QC","Defect prevention","Fault tolerance"],0,"There is checking but no framework of procedures and standards."),
  qWritten("Recommend a mix of QA activities for this company and justify it.","Set up QA (a framework of procedures and standards). Prevention: training and standards. Reduction: static (inspections for requirements and code, desk checks) and dynamic (black-box tests against requirements, white-box tests for structure). Static activities find faults early and cheaply; dynamic ones verify behaviour and internal structure.")],
 hints:["Which activities run the program and which do not?","Who takes part in each activity?","Does the tester see the code?","QA is the framework; QC checks the product.","Which finds problems earliest?"],
 solution:sol(["Different review and test activities with no process."],["Static (inspection, walkthrough, desk check) vs dynamic (black-box, white-box); QA vs QC."],["Match each description to its technique."],["Add a QA framework and combine static and dynamic activities."],"Static and dynamic activities complement each other, and QA gives the framework for using them.",["Treating walkthrough and inspection as identical."])},

{id:"ch4-black-white",title:"Two testers, two views",chapter:4,category:"model-identification",difficulty:"easy",minutes:5,
 tags:["black-white"],related:["c4-8"],
 description:"Tester A tests an ATM by entering inputs and comparing outputs to the specification, without seeing the code. Tester B opens the code and designs tests so that every if/else branch runs at least once.",
 questions:[
  qSingle("Tester A is doing:",["Black-box testing","White-box testing","Desk checking","Inspection"],0,"Specification-based, no code needed: black-box (functional)."),
  qSingle("Tester B is doing:",["White-box testing","Black-box testing","A walkthrough","Fault injection"],0,"Uses internal structure: white (clear)-box / structural testing."),
  qSingle("Both approaches are examples of:",["Dynamic testing","Static testing","Error source removal","Fault tree analysis"],0,"Both execute the software.")],
 hints:["Does the tester see the code?","Which testing verifies internal structures?","Does the program run in both cases?","What is the difference between static and dynamic?","Which one checks external functions?"],
 solution:sol(["One tester uses spec, one uses code."],["Black-box vs white-box; dynamic testing."],["No code → black-box. Branches → white-box."],["Use both."],"Black-box checks external behaviour; white-box checks internal implementation.",["Calling white-box testing static."])},

/* ======================= CHAPTER 5 ======================= */
{id:"ch5-recovery",title:"Interrupted bank transfer",chapter:5,category:"solution-design",difficulty:"medium",minutes:10,
 tags:["recovery","fault-tolerance"],related:["c5-4"],
 description:"A bank transfer debits Account A, but the network fails before Account B is credited. Separately, a billing system discovers it charged a customer too much last night and decides to credit the difference today instead of undoing the original charge.",
 questions:[
  qSingle("Restoring the transfer to its earlier consistent state is:",["Backward recovery","Forward recovery","Fault injection","Voting"],0,"Backward recovery undoes actions and returns to a past consistent state."),
  qSingle("Crediting the difference using compensation information is:",["Forward recovery","Backward recovery","Static testing","Replication"],0,"Forward recovery continues and corrects through compensation."),
  qSingle("Backward recovery needs:",["A recovery point that preserves information","A voter","A data re-expression algorithm","A fault tree"],0,"A recovery point established during execution."),
  qWritten("Which recovery type suits the interrupted transfer? Justify and explain what the system must keep.","Backward recovery: undo the debit and return to the consistent state before the transfer, then retry. The system must create a recovery point, preserving the information needed to restore state. Forward recovery would instead continue and send compensation information, which suits the billing correction.")],
 hints:["Does the system go back or carry on?","What must be saved to go back?","Which case undoes, which compensates?","Which suits the transfer?","What can go wrong without a recovery point?"],
 solution:sol(["Transfer interrupted midway.","Billing overcharge."],["Backward and forward recovery."],["Transfer → backward. Billing credit → forward (compensation)."],["Create recovery points before transfers."],"Backward recovery restores a consistent state; forward recovery corrects and continues.",["Mixing up the two recovery types."])},

{id:"ch5-technique-id",title:"Name that fault-tolerance technique",chapter:5,category:"model-identification",difficulty:"medium",minutes:12,
 tags:["diversity","recovery-block","nvp","nscp","retry"],related:["c5-6","c5-7","c5-8","c5-9","c5-10","c5-11","c5-12"],
 description:"A safety team reviews five designs: (A) the primary routine fails its acceptance test, state is restored and an alternate runs; (B) independently developed versions run in parallel and a voter picks the output; (C) each version has its own acceptance test and the highest-ranking passing version's output is used; (D) one routine is re-run with the input re-expressed; (E) data re-expression algorithms feed at least two copies that run in parallel and a decision mechanism picks the result.",
 questions:[
  qMatch("Identify each design.",["Recovery Block","N-Version Programming","N-Self-Checking Programming","Retry Block","N-Copy Programming"],[["(A) Primary fails the acceptance test; alternate after state restore",0],["(B) Parallel versions with a voter",1],["(C) Own acceptance test per version; highest-ranking passing version wins",2],["(D) One routine re-run with re-expressed input",3],["(E) DRAs, parallel copies, decision mechanism",4]],"RB = sequential alternates + acceptance test. NVP = voter. NSCP = own tests. RtB = data diversity retry. NCP = data-diverse NVP."),
  qSingle("Which approach is cheaper to implement?",["Data diversity (one version)","Design diversity (several versions)","Both cost the same","Neither can be cheaper"],0,"Design diversity needs several independently developed variants."),
  qSingle("The fundamental difference between NVP and Recovery Blocks is:",["NVP uses a voter","RB uses a voter","NVP uses one version","RB has no acceptance test"],0,"The voter is the fundamental difference."),
  qWritten("A flight-control module can fail on rare input values. Choose one design diversity and one data diversity technique and compare cost and benefit.","Design diversity: Recovery Blocks or N-Version Programming, using independently developed versions; high development cost but protection against design faults. Data diversity: Retry Block or N-Copy Programming, using one version with re-expressed input; cheaper and effective when failures depend on particular inputs. Compare by cost, independence of failures and speed.")],
 hints:["Is there a voter, an acceptance test, or both?","Is the data changed or the algorithm?","Sequential or parallel?","Which uses one version only?","What does each cost?"],
 solution:sol(["Five designs with different mechanisms."],["Design diversity: RB, NVP, NSCP. Data diversity: RtB, NCP."],["Identify voter / acceptance test / data re-expression in each."],["Choose by cost and fault type."],"Design diversity uses multiple versions; data diversity uses one version with changed input data.",["Confusing NSCP with RB or NVP."])},

{id:"ch5-detection-degrade",title:"Detect, degrade, inject",chapter:5,category:"model-identification",difficulty:"easy",minutes:7,
 tags:["fault-tolerance","redundancy","fault-injection"],related:["c5-2","c5-3","c5-5"],
 description:"An e-commerce site loses its recommendation service, but browsing and checkout continue with plain product lists. Two copies of the price service get the same input and their outputs are compared. A watchdog raises an alarm if the payment service does not answer within 5 seconds. The team also switches off a database server on purpose to see if recovery works.",
 questions:[
  qMatch("Match each observation to a concept.",["Graceful degradation","Replication (error detection)","Temporal (error detection)","Fault injection"],[["Site continues with reduced features after a failure",0],["Two copies get the same input and outputs are compared",1],["Alarm if no response within 5 seconds",2],["Deliberately switching off a server to test recovery",3]],"Degradation = reduced but proper operation. Replication compares outputs. Temporal watches a time interval. Fault injection tests under abnormal circumstances."),
  qSingle("All fault tolerance activities are based on:",["Redundancy","Documentation only","Marketing","Inspection"],0,"Redundancy for detection and recovery."),
  qMulti("Select ALL forms of redundancy named in the lecture.",["Hardware","Software","Time","Information"],[0,1,2,3],"Hardware, software, time and information.")],
 hints:["Which statement describes reduced but working?","Which compares outputs?","Which uses a timer?","Which tests on purpose?","What do all of them rely on?"],
 solution:sol(["Four different fault-tolerance behaviours."],["Graceful degradation, replication, temporal detection, fault injection."],["Match each behaviour to its definition."],["Combine detection with recovery and test it."],"Fault tolerance relies on redundancy to detect errors and keep operating.",["Confusing replication with temporal detection."])},

{id:"ch5-fta",title:"Why can't customers pay?",chapter:5,category:"problem-diagnosis",difficulty:"hard",minutes:15,
 tags:["fta"],related:["c5-13"],
 description:"A payment company analyses the top event “Customers cannot pay”. It occurs if the payment server crashes (probability 0.02) OR if both the network is down (0.10) AND offline mode is disabled (0.50). Assume the events are independent.",
 questions:[
  qSingle("Fault Tree Analysis is:",["A top-down, deductive analysis using Boolean logic","A bottom-up testing method","A cost model","A kind of voting"],0,"Start from an undesired state and combine lower-level events with AND/OR."),
  qSingle("“Network down AND offline mode disabled” uses which gate?",["AND","OR","XOR","NOT"],0,"Both must happen."),
  qSingle("What is the probability of the top event (rounded)?",["6.9%","0.2%","12%","52%"],0,"AND = 0.10 × 0.50 = 0.05. OR = 1 − (1−0.02)(1−0.05) = 0.069."),
  qSingle("FTA was developed in 1962 at Bell Labs by H.A. Watson to evaluate:",["The Minuteman I ICBM launch control system","An online bank","A compiler","A game engine"],0,"Under a US Air Force contract."),
  qWritten("Using the fault tree, recommend how to reduce the risk of the top event and explain the effect.","The server crash path (OR) alone contributes directly (2%). The network path needs both events, so enabling offline mode removes the AND combination and reduces its probability toward zero. Also improve server reliability (redundancy). The tree supports accident elimination, reduction and control.")],
 hints:["Is it AND or OR at the top?","Compute the AND branch first.","Combine with OR: 1 − product of (1 − p).","Which path is easiest to make safer?","What are the three uses of the tree?"],
 solution:sol(["Two paths cause the top event."],["Fault Tree Analysis: AND/OR logic and probability."],["AND = 0.05; OR = 0.069."],["Enable offline mode; add server redundancy."],"FTA shows which combinations of events cause the accident, so you can eliminate, reduce or control them.",["Adding probabilities instead of using AND/OR rules."])}
];

/* finalise: stable question ids, published flag */
SCENARIOS.forEach(s=>{s.published=s.published!==false;s.questions.forEach((q,i)=>{q.id="q"+(i+1)})});
